INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','احصل على دليل عملي لإدارة الآفات والامراض في محاصيل الذرة الرفيعة عند استخدام نظام الري بالتنقيط، مع نصائح حول المكافحة المتكاملة والوقاية المناسبة للفلاحين العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
