INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Сурго миёни муҳимтарин дони зерҳанҷарост, ки барои саботнокшавӣ ба хушкӣ дар бисёр минтақаҳои нимхушк ва хуши ҷаҳон мекашанд. Бо афзоиши фишори иқлимӣ ва маҳдудияти манбаъҳои об, деҳқонон ба самти усулҳои нав аз обёрӣ, ба монанди обёрӣ бо қатра ва банди нави (типо) мегарданд. Гарчанде ки ин усулҳо самаранокии оби механдонанд, вале тағйиротеро дар микроландшафтҳои минтақаи рӯйӣ ва хок эҷод мекунанд, ки метавонад ба паҳншавии зарароварон ва бемориҳои сурго таъсир расонад. Фаҳмиши ин таъсири мутақобила калиди афзун кардани самаранокии кор ва кам кардани зарарҳо дар кӯшоҳои муосир аст. Дар ин мақола баррасии чуқури ин мавзӯъҳо бо таваҷҷуҳ ба идоракунии занҷирӣ ва пешгирии бемориҳо омадааст.</p>\n<h2>Таъсири муҳити ратубат ба паҳншавии бемориҳои қисми қарағӣ дар сурго</h2>\n<p>Обёрӣ бо қатра, бо нигоҳ доштани ратубат дар атрофи минтақаи қатра (лента) ва хушкшавии тезтари сатҳи хок дар фосилаҳои байни хатҳо, дугонагии махсусеро эҷод мекунад. Бисёр бемориҳои қисми қарағӣ, ба монанди пӯли рӯйӣ ва гилиоцерила, ба ратубати доимӣ дар чуқурӣ ниёз доранд. Гарчанде ки обёрӣ бо қатра метавонад бо назорати дақиқтари ҳаҷми об аз таҳалуккунии умумии дарозмуддат манъ кунад, вале агар фосилаҳои хатӣ калон бошанд ё заҳкунӣ мувофиқ набошад, ратубати монда дар минтақаи қатра метавонад марказ барои қисми қарағии хокӣ шавад. Аз тарафи дигар, банди нави (типо), ки намуди обёрӣ бо қатра аст, метавонад бо эҷоди банди маҳдуди ратубат пайҳомшавии ҳосили наъмакшудаи сатҳиро кам кунад ва бо кам шудани наъмакшудагон паноҳгоҳи зарароваронро маҳдуд созуд. Барои фаҳмиши беҳтари механизмҳои физикӣ ва гидрокӣ, ки ин таъсирҳоро эҷод мекунанд, омӯзиши хусусиятҳои банди нави (типо) ва сифатҳои он тавсия дода мешавад.</p>\n<h3>Идоракунии пӯли рӯйӣ ва голду</h3>\n<ul>\n<li><strong>Пӯли рӯйии фосокария:</strong> Дар системаҳои қатқаторӣ, агар барномаи обёрӣ хеле ғализ бошад, таъминоти оксиген ба решаҳои сургоҳ халалӣ меёбад. Бо зиёд кардани фосилаи вақтии обёрӣ ва кам кардани миқдори ҳар бор, метавон мувозинати об-оксигенро барқарор кард.</li>\n<li><strong>Гулду ва занги сургоҳ:</strong> Ин бемориҳо бештар вобаста ба намуди нисбии баланди баргҳо мебошанд. Азбаски қатқаторӣ намудро дар реша ғализ мекунад ва на дар тӯп, хатари гирифтан ба зангиҳо нисбат ба обёрии сатҳӣ кам мешавад. Бо вуҷуди ин, истифодаи аرقامҳои муқовиматангез ҳанӯз ҳам ҳаётӣ аст.</li>\n</ul>\n<h2>Тағйироти аҳолии зараррасонҳо дар системаҳои обёрӣ бо қувваи паст</h2>\n<p>Яке аз фоидаҳои пинҳонии системаҳои обёрии қатқаторӣ ва навартип кам шудани аҳолии баъзе зараррасонҳои ҳашаракӣ аст, ки барои эволюсия ба намуди сатҳи хок ё ҳашароти паразитӣ ниёз доранд. Кулакҳои хокӣ ва баъзе шопаракҳо дар хоки ҳамеша тар фаъолияти баландтар доранд. Идоракунии дақиқи намуд метавонад даври ҳаёти баъзе бачаҳои кулакҳои решабориёнро халал доҳад. Инчунин, кам шудани отаҳои бемор дар минтақаи навари намнок (аз сабаби рақобат бо сургоҳ ва шори нисбӣ) паноҳгоҳи муносиб барои капсидинҳо ва шопаракҳои хокӣро нобуд мекунад.</p>\n\n<h3>Зараррасони сегоҳӯр ва данаӯр</h3>\n<p>Сургоҳ нисбат ба хашакҳои сегоҳӯр ва данаӯр, махсусан дар марҳилаи рушди по, ба осонӣ зарар мебинанд. Гарчанде ки обёрии қатқаторӣ бевосита ба ин зараррасонҳо таъсир намерасонад, вале саломатии беҳтар, ки ба растани мебахшад, муқовимати растаниро нисбат ба дохилшавии ин зараррасонҳо зиёд мекунад. Растание, ки аз ҷиҳати ғизоӣ қавӣ аст, зудтар қобилияти муқовимат ба дорухӯрии ҳашаротро пайдо мекунад. Дар минтаҳое, ки партовии мозаика ё вирусҳо низ паҳн аст, идоракунии суутум шудан тавассути бурардиҳандагон (нумул ва шопарак) муҳимияти дучанд дошта аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سورگوم-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های سورگوم با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation сургоҳ</figcaption></figure>\n<h2>Нақши шуморакӣ ва EC дар идоракунии бемориҳои хокӣ</h2>\n<p>Яке аз мушкилоти асосӣ дар обёрӣи қаъқатӣ ҷамъшавии намакҳо дар минтақаи равон аст. Соргум қисман ба шуморакӣ тоқмет аст, аммо шумораки баланд метавонад стресси физиологӣ ба вуҷуд орад, ки растаниро нисбат ба бемориҳои иқтимодӣ ҳассостар менамояд. Дар ин ҳолат, мубаззотҳои фаъол (опортунистӣ) фурсат пайдо мекунанд, ки дохил шаванд. Аз ин рӯ, назорати EC-и оби обёрӣ ва интихоби риштаи мувофиқ бо назардошти сохти хок зарур аст. Барои таъмини дурустии система, ошноӣ бо нуқтаҳои муҳими пеш аз насби риштаи тип дар боғтӯлорӣ метавонад пешгирӣ мушкилоти оянда бигарад.</p>\n\n<h2>Стратегияҳои амалӣ барои идоракунии зараррасонҳо ва бемориҳо</h2>\n<h3>1. Идоракунии сифатӣ ва чархзаниҳои кишт</h3>\n<p>Дар системаҳои обёрӣи қаъқатӣ, имкони пайвандани анвои растаниҳо ба як суръати яклухт мавҷуд аст. Чархзанӣ бо растаниҳое, ки ҳоссосияти гуногун ба зараррасонҳои сургум доранд, метавонад доираи ҳаёти зараррасониҳои хокиро бишиканад. Мисолан, киштани яксола растаниҳое, ки системаи решаи гуногун доранд, метавонад шумораи кӯрдуҳҳои ресаро коҳиш диҳад. Инчунин, истифодаи омехтаи бубо бо растаниҳои кампанӣ, ки хусусияти ғайринилобишавандаро доранд, дар риштаҳои қубарӣ метавонад самаранок бошад.</p>\n<h3>2. Идоракунии биологӣ дар шароити намёргии назоратшуда</h3>\n<p>Муҳити устувори микрокллубӣ, ки аз ҷониби обёрӣи қаъқатӣ ба вуҷуд меояд, барои душманони табиӣ, ба монанди мубаззотҳои муҳофизакунанда (Trichoderma), идеалӣ аст. Ин мубаззотҳои фоиданок метавонанд дар хокҳои намёргии доимӣ беҳтар аз мубаззотҳои беморангез рушд кунанд ва растаниро ҳифз кунанд. Истифодаи бубоҳои бо Trichoderma пӯшонидашуда дар киштҳои сургум яке аз роҳҳои арзон ва устувор аст. Барои фаҳмиши беҳтари ин раҳоҳои биологӣ ва нақши системаҳои обёрии нав, омӯзиши роҳнамои ҷамъбасти <a href="https://navar-abyari.ir/loe-nakhi-90-irrigation-guide/">Роҳнамои обёрӣи лентаи пашми 90</a> Ҳамчун намунаи намунаҳои ороиши дақиқ, корбурдор мешавад.</p>\n<h3>3. Пайҳангоии динамикаӣ ва ҳудуди иқтисодӣ</h3>\n<p>Ба ҷои маҳвкунандагӣи пешгирокунандаи бемаъно, ки дар усулҳои кӯҳнаи ороенӣ муътод буд, дар усулҳои даққатонавӣ бояд аз пайҳангоии даврагӯн барои паразитҳои сурҳум бо ороиш даққатонавӣ истифода бурд. Бо баъдат баро наздиксавӣ бо об, зичии зарароварони ҳашарот метавонад тезтар ҷолиб кунад. Муайян кардани ҳудуди иқтисодӣ барои ҳар як зараровар махсус, аз рафторноксавии манбаъҳои таъсиррасонӣ пешгирӣ мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سورگوم-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های سورگوم با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation сурҳум</figcaption></figure>\n<h2>Муқоисаи ҳомили: ороиш даққатонавӣ ба мубодилаи нуқобӣ</h2>\n<p>Интихоби байни даққатонавӣ ва нуқобӣ, аз рӯи гунаи хок ва паразитҳои асосии минтақа тағйир меёбад. Нуқобӣ арзишти беҳтар дорад ва барои минтақаҳои калон мувофиқ аст, аммо идоракунии дақиқтар дар минтақаи даҳлӯн бо даққатонавӣ метавонад ба кам шудани хавфи бемориҳои қарорӯсии реша кӯмак кунад. Агар хок сабук бошад ва равонӣ тез бошад, нуқобӣ интихоби беҳтар аст. Дар хокҳои вазнин бо часибӣ баланд, даққатонавӣ бо фишори кам, таҳавули амиқтар ва устувории намнокӣ мебахшад. Барои интихоби фосилагирии дуруст, ки ба пуркарагии зарароварон низ таъсир мерасонад, омӯзиши фосилаи нуқобӣ дар самти кишт ба андозаҳои замин роҳнамӯи мувофиқ аст.</p>\n\n<h2>Саволҳои муносиб (FAQ)</h2>\n<h3>Оё ороиш даққатонавӣ боиси зиёд шудани хушкҳоки хокӣ дар сурҳум мекунад?</h3>\n<p>Шаҳодат. Агар ғайбнамоиш ва намоиҳои хушкӣ дуруст иҷро шаванд, зичии кӯрҳои ғаллодат одатан кам мешавад. Зеро ғалладат дар ҷустуҷӯии намӣ дар сатҳи хок фаъол мебошанд ва чуқурӣ намро нигоҳ медорад. Аммо агар намоиш заиф бошад, хатари зиёд шудани намии тӯлонӣ ва дар натиҷа баланд шудани ҳашароти хокӣ вуҷуд дорад.</p>\n<h3>Бештарин вақт барои назорати бемориҳои решагуна дар системаҳои нав чист?</h3>\n<p>Вақти беҳтарин пеш аз марҳилаи куштнокӣ ва ҷӯронӣ, ва дар моҳҳои гарми сол, вақте ки гиёҳ дар стресси афзоиш қарор мегирад. Бо гирифтани намунаи реша аз минтақаи таъсирдиди чуқурӣ, метавон намунаҳои фасодшавиро баъдтар муайян кард.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-سورگوم-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های سورگوم با آبیاری قطره‌ای - تصویر 3"/><figcaption>ҳашарот ва бемориҳои ғаллодат, оҳиши чуқурӣ, саргонӣ</figcaption></figure>\n<h3>Оё барои назорати ҳашарот дар оҳиши чуқурӣ аз гузаронандаҳои кимиёвӣ истифода кардан мумкин аст?</h3>\n<p>Баъзе зараргарии кимиёвӣ барои ҳашаротҳои рӯйи рӯй хориҷи оҳиши чуқурӣ (Кимиёвизатсия) маъруфанд. Аммо ин кор ба дониши баланд ниёз дорад, то аз зарари лантҳо ва системаи филтр пешгирӣ карда шавад. Тавсия мешавад, ки аз омехтаҳои биологӣ ё хокбурӣ истифода барда шавад, магар ин ҳолати ошубонна будааст.</p>\n<h2>Хулоса</h2>\n<p>Идоракунии ҳашарот ва бемориҳои саргонӣ бо оҳиши чуқурӣ, як усули ягоназудаи омезиши назорати муҳитӣ, бехатарӣ ва агар зарур бошад, кимиёвӣ мебошад. Системаҳои оҳиши дақиқ, чун намоиши типӣ ва чуқурӣ, асбороти қудратманд ҳастанд, ки агар бо дониши идоракунии омезишӣ (IPM) мувофиат кунанд, метавонанд хосаратро ба камтарин дараҷа расонанд. Диққат ба бехатарии хок, назорати мунтазам ва интихоби навиштаҳои муқовиматӣ, се пойгаи асосии муваффақият дар ин усулҳост. деҳқонҳо бо истифода аз ин стратегияҳо на танҳо истеҳлотро зиёд карда, балки устувориби муҳити зист ва саломати маҳсулоти худро низ таъмин карда мекунанд. Барои ҷӯронии дигар маҳсулоти кишоварзӣ, ки ба оҳиши чуқурӣ ниёз доранд, таҳқиқоти фосилаи намоиши типии сафуна метавонад намуна барои муқоиса ва мутобиқсозии стратегияҳои монанд бошад.</p>\n<p><strong>Мавзӯи бандидашуда:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%db%8c%d9%88%d9%86%d8%ac%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бардики чангӯла дар гектар + омилҳои таъсиррасон (беҳтарин роҳ)</a>، <a href="https://navar-abyari.ir/%d8%ae%d8%b5%d9%88%d8%b5%db%8c%d8%a7%d8%aa-%d9%88-%d9%88%db%8c%da%98%da%af%db%8c%d9%87%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be/">Хусусиятҳои нави пип ва хосиятҳои он</a>، <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A7%D8%B3%D9%BE%D8%B1%D8%B3-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8A7D8B3D9BED8B1D8B3 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Модиратии зарароварон ва бемориҳои сорго дар системаи обёривии қатрагӣ: Рӯшноиёми ҷамъӣ','Сургум ҳамчун як донои муҳим дар минтақаҳои камобӣ, ба баъзе зараррасонҳо ва бемориҳои хоси он майл аст. Истифодаи системаҳои обории заррагӣ (доп) ва наубарҳо метавонад муҳити рӯшйи ғольро тағйир диҳад ва ба идоракунии беҳтари ин мушкилот кӯмак расонад. Дар ин мақола мо бо муфассалоти техникии ин алоқа ва роҳҳои амалӣ ошно мешавем.','publish','closed','closed','modiratii-zararavaronu-bemorihai-sorgo-dar-systemai-oboriyii-qttarga',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
