INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти идоракунии зарарангорон ва бемориҳо дар шӯрбаламолшавии булоти қатрагӣ</h2>\n<p>Шӯр бо яке аз нолиҳои муҳими донӣ аст, ки дар минтаҳоҳои зиёди шароити иқлимии муносиб кишт мешавад. Бо васеъшавии системаҳои нави обёркунӣ, ба монанди қатрагӣ ва тиби банд, деҳқонон дар пайи зиёд кардани самаранокии истифодаи об ва беҳтар кардани сифати маҳсулот мебошанд. Аммо яке аз вазъиятҳои асосӣ дар кштии шӯр дар зери ин системаҳо, идоракунии дуруст <strong>зарарангорон ва бемориҳои шӯр бо обёркунӣи қатрагӣ</strong> ост. Гарчанде ки обёркунӣи қатрагӣ боиси кам шудани намӣи сатҳии хок ва дар натиҷа кам шудани баъзе бемориҳои қабисӣ мегардад, вухат шараит барои фаъолияти бештари баъзе зарарангорони хоки майда ё бемориҳои ҷавороӣ эҷод мекунад. Бинобар ин, шиносоии дақиқи ин робитаҳо ва қабули стратегияҳои мувофиқ, калиди муваффақият дар кштии шӯр аст.</p>\n\n\n\n<h2>Таъсири системаҳои обёркунӣи қатрагӣ ба муҳити истиқомоти зарарангорон ва бемориҳо</h2>\n<h3>Тағйирот дар намии нисбӣ ва сатҳӣ</h3>\n<p>Яке аз имкониятҳои асосии обёркунӣи қатрагӣ, марказгиркунии намӣ дар минтақаи решаҳо ва кам шудани намӣ дар фазо байни сатҳҳо аст. Ин кор метавонад аз паҳншавии тезтари бемориҳои ҷаворӣ, ба монанди захобҳои қабисӣ, оҳиста кунад. Аммо аз тарафи дигар, хушкӣи нисбии сатҳи хок метавонад ҳаваси баъзе зарарангорони ҳашаротбаро барои миграцияи чуқуртар ё фаъолият дар сатҳҳои баландтарро зиёд кунад. Инчунин, ҷамъшавии об дар нуқтаҳои махсуси тиби банд дар ҳолати ноҳамвории замин, метавонад острҳои намӣ эҷод кунад, ки ҷои муносиб барои рушди қабисҳои хокизӣ ба монанди <em>Phytophthora</em> ё <em>Fusarium</em> ст</p>\n\n<h3>Таъсири тарзи ғизоии растани ва бегомии он</h3>\n<p>Растании абраш ба stress-и микроғизоҳо ҳассос аст. Дар системаҳои намонокии қатрагӣ имкони тақсими дақиқи наврокҳо вуҷуд дорад, вале истифодаи нодуруст метавонад боиси заифии растани ва зиёдшавии бегомии он бар асри зараррасониҳо гардад. Растаниҳое, ки бо камбуди нитроген ё потасий рӯбарӯ ҳастанд, одатан бегомии камтари бар зидди ҳуҷуми зараррасониҳо доранд. Аз ин рӯ, идоракунии муواзоти <strong>наврок ва об</strong> дар ин системаҳо зарур аст. Барои фаҳмиши беҳтар аз омилҳое, ки бар самаравӣ ва сифати ҳосил таъсир мерасонанд, омӯзиши маҳсулоти ихтисосӣ дар соҳаи [Омилҳое, ки бар самаравии ҳектари абраш таъсир мерасонанд](https://navar-abyari.ir/syrindbin-yield-per-hectare-factors/) тавсия дода мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ارزن-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های ارزن با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation абраш</figcaption></figure>\n\n\n\n<h2>Зараррасониҳои муҳими абраш ва роҳи идоракунии онҳо дар шароити намонокии қатрагӣ</h2>\n<h3>Зараррасониҳои хокзаҳои ҳашараҳо</h3>\n<p>Ҷавонон чун <strong>кизакҳои хок</strong> ва <strong>мураҳои хушканд</strong> Дар шароити нобмуни назоратшуда бо системаи қатқатӣ мумон аст рафтори гуногун намоянд. Гарчанде нобмуни поёни сатҳӣ фаъолияти баъзе аз ин зараррасонҳоро маҳдуд мекунад, аммо агар хок хеле хушк шавад, баъзе зараррасонҳо ҷузъонони бартарии намнокӣ ба сӯи хатҳои оварии об ҷозиба мешаванд. Барои назорати ин зараррасонҳо истифода аз тлаҳои зардӣ ва назорати мунтазами сохтори хок зарур аст. Инчунин, сикли камбаст ва истифода аз нусхаҳои муқовиматноки метавонад нақши бартарии дошта бошад.</p>\n\n<h3>Зараррасони дарагул ва пошакҳо</h3>\n<p>Ҳуҷуми зангҳо ва шаткиҳо (Pegomya) ба дарагулҳои кумм ҳатто дар шароити оварии об бо системаи қатқатӣ рух дода метавонад, зеро ин зараррасонҳо бевосита ба гијат мераванд. идоракунии ин зараррасонҳо бештар ба интихоби нусхаҳои муқовиматнок ва зараррасонӣ дар лаҳзаҳои ҳассос вобаста аст, на ба шароити оварии об. Аммо диққат диҳед, ки зараррасонӣ бо системаи қатқатӣ ниёз ба дақиқии махсус дорад, то ба лӯлаҳо ё нӯриҳо осеб нарасонад. Дониши намуди нӯриҳои қатқатӣ ва муқовимати онҳо нисбат ба моддаҳои кимиёвӣ аз роҳи таҳқиқ [намуди нӯриҳои оварии қатқатӣ](https://navar-abyari.ir/types-of-drip-tape-irrigation-tubes/) метавонад дар интихоби системаи мувофиқ кӯмак расонад.</p>\n\n\n\n<h2>Бемориҳои қарами ва бактериявии кумм дар оварии об бо системаи қатқатӣ</h2>\n<h3>Губишди реша ва занг</h3>\n<p>Дар ҳоле ки обёрӣи қатравӣ аксар вақт хатари губишди решаи решаи решаи решаи решаиро коҳиш медиҳад, аммо дар сурати озолишди аввалияи хок, рутубати доимӣ ва назоратшуда метавонад ба инкишофи ин бемориҳо кӯмак расонад. Аломатҳои аввуму бошад бо зарди баргҳои поёнӣ ва заифии ҳарча мебошад. Барои пешгири, истифодаи хокҳо бо зиракати мувофиқ, назорати хок ва навигонҳои муқобилатнок ба губишди реша муҳим аст. Инчунин, истироҳати кӯҳорӣ метавонад давраи зиндагии зейроро буғад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ارزن-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های ارزن با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation арзон</figcaption></figure>\n\n<h3>Бемориҳои барги зейро</h3>\n<p>Бемориҳои баргӣ, монанди бемадори барги арзон ё занг, оҳиста-оҳиста зери обёрӣи қатравӣ камтар паҳн мешаванд, зеро сатҳи барг хушкитар аст. Аммо агар обёрӣи қатравӣ бо шакли пастра (микропостреннела) анҷом шавад, хатар зиёд мешавад. Бинобар ин, истифодаи қатрагулҳои стандартӣ ва пайҳат кардани нам кардани сатҳи ҳарча калиди идоракунии ин бемориҳо мебошад. Дар ин роҳ, шинос шудан бо принсипҳои [Обёрӣи хресобӣ чист? Хусусиятҳо ва камбудиҳо](https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%ae%d8%b1%d8%b3%d8%a7%d8%a8%db%8c-%da%86%db%8c%d8%b3%d8%aa%d8%9f-%d9%88%db%8a%da%87%da%af%db%8a-%d9%87%d8%a7-%d9%88-%d9%85%d8%b9%d8%a7%db%8c%d8%a8/) метавонад диди умумиютари усулҳои обёрӣи муваффақ ва таъсири онҳо ба саломатии ҳарчаро фароҳам орад.</p>\n\n<h2>Нуктаҳои амалӣ барои деҳқонон ва муҳандисон</h2>\n<ul>\n<li><strong>Назорати мунтазами хок:</strong> Ҳар 2 то 3 ҳафта як маротиба намунабардории хок аз зер хати нӯри дрип ба анҷом расонида шавад, то аз ҷамъшавии намак ё тағйироти PH пешгирӣ карда шавад, ки метавонад реша ҳассостар кунад.</li>\n<li><strong>Идоракунии мутамаррази зараранкаран (IPM):</strong> Муҳофиат кунед ба ҳашарҳои фоидаовар дар майдон. Дар системаи нақтнокӣ, кам шудани зиёдашии баъзе зараранкаран имконияти хубро барои баргашти ҳашарони фоидаовар фароҳам меорад.</li>\n<li><strong>Шустани системаи обёрӣ:</strong> Истифодаи хлор ё моддаҳои кимиёвӣ барои шустани лулӯҳо аз ихтилати лентаҳои давидӣ пешгирӣ мекунад, ки худ метавонад ба фишори кӯҳна ва зиёд шудани эҳтимоли зарардидашавӣ аз ҷониби зараранкаран боис шавад.</li>\n<li><strong>Бурҳои кӯҳна:</strong> Барои беҳтар кардани идоракунии зараранкаран, донистани [миқдори бурҳои кӯҳна дар гектар]([https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%A8%D8%A7%D9%82%D9%84-%D8%AE%D8%B4%DA%A9-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/]) зарур аст, то зиёд шудани гулҳо боиси ҳавои беҳтар байни кӯҳнаҳо шавад.</li>\n<li><strong>Пешгирии обёрии зиёда:</strong> Рӯидаги зиёда дар зери лента метавонад ба рушди қайғон кӯмак кунад. Вақтгузорӣ обёрӣ мувофиқи фишори матриси хок тавсия дода мешавад.</li>\n</ul>\n\n<p>Шунъ инчунин, дар симои эҳтиёҷ ба иваз кардани нурунҳои ғиле ӯҳрифта буда, шиносӣ [интихоб кардани нуруни ғилеи киштӣ] (https://navar-abyari.ir/%D8%A7%D9%86%D8%AA%D8%AE%D8%A7%D8%A8-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%DA%A9%D8%B4%D8%A7%D9%88%D8%B1%D8%B2%DB%8C/) дар асоси навъи хок ва зичии арз метавонад аз пошадани маводи ҳосил аз ҳамаи стресс об ва натиҷае аз зиёд шудани зарар ба мавад ва мавҷидон пешгирӣ кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-ارزن-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های ارزن با آبیاری قطره‌ای - تصویر 3"/><figcaption>мавад ва бемориҳои ҳосилот суғро кардани ғиле арз</figcaption></figure>\n\n<h2>Саволҳои мулоим (FAQ)</h2>\n<ol>\n<li><strong>Оё суғро кардани ғиле боиси зиёд шудани зарарҳои ҳашарот дар арз мегардад?</strong><br> Аз ҳеҷ маъное, вале метавонад нақши тақсимоти зарарҳоро тағйир диҳад. Баъзе зарарҳои хокӣ шояд дар наздикии хатҳои суғор ҷамъ оранд. Таъмини ҳосилоти муҳоварӣ боз ҳам зарур аст.</li>\n<li><strong>Беҳтарин замон барои ғилеи маҳаллӣ чӣ ишора аст?</strong><br> Ғиле кардан бо ғиле ғиле танҳо дар симои муштуми маҳаллӣ ва истифодаи моддаҳои махсус барои системаҳои суғор имконпазир аст. Ин корро бояд дар замони набудани об (поёнони субҳ ё шаб) иҷро кард, то аз баъди шӯр ва ғилеи ғилеи нурун пешгирӣ шуд.</li>\n<li><strong>Оё ифтиҳоршудани нуруни ғиле мустақиман бо бемории решаҳо алоқаманд аст?</strong><br>Бале, нақсӣи реша барои обёрории нокифоя ё номувофик, мусоидатро кӯҳон мекунад. Баъди зарари зиёдатаре аз ҳашарот ва зангҳо наметавонад. Бинобар ин, саломати системаи обёрдорӣ ба таври мустақим бо саломати раста пайваст аст.</li>\n<li><strong>Оё аз навари ришавӣ барои кишт баҳул (гурх) истифода кардан мумкин аст?</strong><br> Бале, навари ришавӣ бо қабати 16 ё 20 миллиметр одатан барои баҳул истифода мешавад. Интихоби қабати мувофиқ тавассути таҳқиқи [вижагиҳои ришавӣ барои тавозун дар ҳолати бӯнӣ](https://navar-abyari.ir/%D8%B4%D8%B1%DB%8C%D8%B7-%D8%A7%D9%84%D8%B1%DB%8C-%D8%A8%D8%A7%D9%84%D8%AA%D9%86%D9%82%DB%8C%D8%B7-%D9%81%DB%8C-%D8%AD%D9%84%D8%A8%DA%86%D9%87/) ва мутобиқ шудан бо шароити замина иҷро мешавад.</li>\n</ol>\n\n<h2>Хулоса</h2>\n<p>Корбарӣ <strong>Зангҳо ва бемориҳои баҳул бо обёрории қатрагӣ</strong> Лозим аст, ки наздик ба реша, хок, раста ва системаи обёрдорӣ ҳисоб шуда, як ягон нақшаи умумӣ истифода шавад. Фоидаҳои кам шудани намии сатҳӣ ва идоракунии дақиқи ғизо, бояд бо назорати саломати ҳашарот ва бемориҳои хокӣ ҳамроҳ бошад. Бо интихоби нависҳои муқовиматнок, наздик мондани мунтазам ва нигоҳдории дурусти системаи навари ришавӣ, деҳқонҳо метавонанд дар ҳамон вақте, ки обро нест мекунанд, аз зариби иқтисодӣ, ки аз ҳашарот ва бемориҳо ба вуҷуд меоянд, кам мекунанд ва ҳосилнокии устувориштарро таъмин мекунанд. Ошноӣ бо манбаъҳои ихтисосӣ, ба монанди [миқдори таъсири ғаллодаи соя дар гектар](https://navar-abyari.ir/miqdori-tuhmii-soya-dar-hektar-omilhoi-tasirrason/) ва дигар матнҳои марбут ба ҳосилнокии ғаллодаҳо, метавонад ба фаҳмиши беҳтари омилҳои фаъоли замина кӯмак расонад. Муваффақ будан дар ин роҳ, вобаста ба дониш, дақиқӣ ва риояи принсипҳои илмӣ аст.</p>\n<p><strong>Мақолаҳои марбут:</strong> <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%ae%d8%b1%d8%b3%d8%a7%d8%a8%db%8c-%da%86%db%8c%d8%b3%d8%aa%d8%9f-%d9%88%db%8c%da%98%da%af%db%8c-%d9%87%d8%a7-%d9%88-%d9%85%d8%b9%d8%a7%db%8c%d8%a8/">Чистодушӣ чист? Хусусиятҳо ва камбудиҳо</a>， <a href="https://navar-abyari.ir/syrindbin-yield-per-hectare-factors/">syrindbin yield per hectare factors</a>， <a href="https://navar-abyari.ir/types-of-drip-tape-irrigation-tubes/">types of drip tape irrigation tubes</a>， <a href="https://navar-abyari.ir/dill-yield-per-hectare-factors-increase-methods/">dill yield per hectare factors increase methods</a></p>','Вазифаҳо ва бемориҳои зирак бо оборӣ тӯлоқӣ: Раҳнамои ҳосилнок','Ороиши қатараӣ гарчанде самаранокист, вале метавонад шароити мусоидро барои пайдоиши баъзе зараррасонҳо ва бемории гурун мунҷамъ шавад. Дар ин мақола бо роҳҳои пешгирикунӣ, идоракунии комплексӣ ва масъалаҳои амалӣ барои нигоҳдории солиммонии рӯёнда дар ин системаҳо шинос мешавед.','publish','closed','closed','afvat-va-bemorihoi-zerak-oboriyo-tuloqi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
